<?php require __DIR__ . '/includes/cart-render.php'; exit; ?>
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add'||$action==='buy'){ $pid=(int)($_POST['product_id']??0);$code=trim($_POST['size_code']??'');$qty=max(1,(int)($_POST['quantity']??1));$q=db()->prepare('SELECT p.*,s.display_name FROM products p JOIN product_sizes ps ON ps.product_id=p.id JOIN sizes s ON s.id=ps.size_id WHERE p.id=? AND s.code=?');$q->execute([$pid,$code]);$product=$q->fetch();if(!$product){flash('error','Ukuran produk tidak valid.');redirect('shop.php');}$key=$pid.'|'.$code.'|'.($_POST['variant']??'').'|'.($_POST['motif']??'');$_SESSION['cart'][$key]=['product_id'=>$pid,'name'=>$product['name'],'price'=>(float)$product['price'],'image'=>db()->prepare('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order LIMIT 1')->execute([$pid])?null:null,'size_code'=>$code,'size_name'=>$product['display_name'],'variant'=>trim($_POST['variant']??''),'motif'=>trim($_POST['motif']??''),'quantity'=>$qty];$im=db()->prepare('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order LIMIT 1');$im->execute([$pid]);$_SESSION['cart'][$key]['image']=$im->fetchColumn()?:'';if($action==='buy')redirect('checkout.php');flash('success','Produk ditambahkan ke keranjang.');redirect('cart.php');}if($action==='update'){foreach($_POST['qty']??[] as $key=>$q){if(isset($_SESSION['cart'][$key]))$_SESSION['cart'][$key]['quantity']=max(1,(int)$q);}flash('success','Keranjang diperbarui.');redirect('cart.php');}if($action==='remove'){unset($_SESSION['cart'][$_POST['key']??'']);flash('success','Produk dihapus dari keranjang.');redirect('cart.php');}}
$items=$_SESSION['cart']??[];$total=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));$title='Shopping Cart';require __DIR__.'/includes/header.php';?><main class="cart-wrap"><div class="eyebrow">YOUR SELECTION</div><h1 class="serif text-5xl mt-2">Shopping cart.</h1><?php if(!$items):?><div class="bg-white p-10 mt-6 text-center"><p>Keranjangmu masih kosong.</p><a class="btn mt-4" href="<?=url('shop.php')?>">SHOP COLLECTION</a></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="update"><?php foreach($items as $key=>$i):?><article class="cart-row"><img src="<?=e($i['image'])?>" alt=""><div><small><?=e($i['size_name'])?><?= $i['variant']?' · '.e($i['variant']):''?><?= $i['motif']?' · '.e($i['motif']):''?></small><h3 class="serif text-xl mt-1"><?=e($i['name'])?></h3><b><?=money($i['price'])?></b></div><div class="quantity"><button type="button" onclick="this.nextElementSibling.stepDown()">−</button><input name="qty[<?=e($key)?>]" type="number" min="1" value="<?=$i['quantity']?>"><button type="button" onclick="this.previousElementSibling.stepUp()">+</button></div><strong class="subtotal"><?=money($i['price']*$i['quantity'])?></strong><button class="remove text-red-700" formaction="<?=url('cart.php')?>" formmethod="post" name="action" value="remove" onclick="this.form.querySelector('[name=key]').value='<?=e($key)?>'">×</button></article><?php endforeach;?><input type="hidden" name="key"><button class="text-link border-0 bg-transparent cursor-pointer mt-3" type="submit">UPDATE CART</button></form><aside class="summary"><div class="line"><span>Subtotal</span><strong><?=money($total)?></strong></div><div class="line"><span>Pengiriman</span><span>Dihitung kemudian</span></div><hr class="my-4"><div class="line text-lg"><strong>Total</strong><strong><?=money($total)?></strong></div><a class="btn gold w-full mt-4" href="<?=url('checkout.php')?>">CHECKOUT</a></aside><?php endif;?></main><?php require __DIR__.'/includes/footer.php'; ?>
